from qb import q, write

DEV = ["full-stack-developer", "backend-developer", "frontend-developer", "mobile-app-developer", "python-developer"]
ITEMS = [
    q("node", "easy", ["node"], "What is Node.js and why is it good for I/O-heavy servers but weaker for heavy CPU work?", "Node.js runs JavaScript on the server with a single-threaded event loop and non-blocking I/O, so one process can handle many waiting connections. A long CPU task blocks that loop and delays every request, so heavy work belongs in worker threads or another service.", ["Event loop, non-blocking I/O", "CPU work blocks the loop", "Use workers or separate services"], ["How would you find what is blocking the loop?"]),
    q("node", "medium", ["express", "middleware"], "What is middleware in Express and how would you add logging, authentication and error handling?", "Middleware is a function that receives the request, response and next, and can change them or end the response. Register logging first, authentication on protected routes and an error-handling middleware with four arguments last so it catches thrown errors.", ["Functions in a chain", "Order matters", "Error middleware has four arguments"], ["How do async errors reach the error handler?"]),
    q("node", "medium", ["streams"], "Why would you stream a large file download instead of reading it fully into memory?", "Reading a whole file loads it all into memory, which fails for large files and under many users. A stream sends it in small chunks, keeping memory low and starting the response sooner, with back-pressure handling when the client is slow.", ["Memory stays low", "Chunks start sooner", "Back-pressure"], ["How do you handle an error halfway through the stream?"]),
    q("node", "hard", ["scaling"], "Your Node API on one server is at its limit. How do you scale it and what must change in the code?", "Run several processes with a process manager or cluster and put a load balancer in front, which needs the server to be stateless, so sessions and uploads move to shared stores like Redis or object storage. Add caching and measure the real bottleneck first.", ["Several processes behind a load balancer", "Stateless design", "Shared session store and caching"], ["How do WebSocket connections complicate this?"]),
    q("react", "easy", ["react"], "What is the virtual DOM and why does React use it?", "The virtual DOM is a lightweight copy of the UI in memory. When state changes React builds a new version, compares it with the old one and applies only the differences to the real DOM, which makes updates efficient and predictable.", ["In-memory UI representation", "Diffing", "Minimal real DOM updates"], ["Does the virtual DOM always make an app faster?"]),
    q("react", "medium", ["hooks"], "What is the difference between useState and useReducer and when is useRef useful?", "useState suits simple independent values, while useReducer suits state with several related fields and clear actions. useRef keeps a mutable value that survives renders without causing one, such as a DOM element or a timer id.", ["Simple vs structured state", "Actions with a reducer", "Ref does not trigger re-render"], ["How would you focus an input on mount?"]),
    q("react", "medium", ["data-fetching"], "How do you fetch data in a React component and handle loading, error and stale responses?", "Fetch inside an effect or with a data library, keep loading, error and data in state, show each state in the UI and ignore or abort an old response if the component unmounts or the query changes. A library such as React Query adds caching and retries.", ["Loading, error, data states", "Abort or ignore stale responses", "Libraries add caching"], ["What bug appears when two requests return out of order?"]),
    q("react-native", "medium", ["mobile"], "What are the main differences between building with React Native and building fully native apps?", "React Native shares most code across iOS and Android using JavaScript and renders native components, which saves time. Fully native gives the best performance and immediate access to new platform features, while React Native may need native modules for some features.", ["Shared code, native components", "Native for best performance", "Native modules when needed"], ["When would you recommend going native?"]),
    q("python", "easy", ["python"], "What is the difference between a Python module, a package and a virtual environment?", "A module is one Python file, a package is a folder of modules, and a virtual environment is an isolated set of installed libraries for one project so versions do not clash.", ["Module, package, environment", "Isolation of dependencies", "requirements file"], ["How do you record the exact versions you used?"]),
    q("python", "medium", ["fastapi", "flask"], "Compare Flask and FastAPI and say when you would choose each.", "Flask is a small, flexible framework with a huge ecosystem, while FastAPI is built on type hints and gives automatic validation, async support and generated API documentation. FastAPI fits new APIs, and Flask suits small apps or existing projects.", ["Flexible vs typed and async", "Automatic validation and docs", "Choose by project needs"], ["How does FastAPI validate a request body?"]),
    q("api", "medium", ["websockets"], "When would you use WebSockets instead of normal HTTP requests, and what are the challenges?", "Use WebSockets for continuous two-way updates such as chat or live tracking. Challenges are connection limits, reconnection and authentication, scaling across servers with a pub/sub layer and handling lost messages.", ["Two-way live connection", "Reconnect and authenticate", "Scale with pub/sub"], ["How do server-sent events compare?"]),
    q("api", "hard", ["rate-limiting"], "How would you implement rate limiting for a public API?", "Count requests per key, such as user or IP, in a fast store like Redis using a fixed window, sliding window or token bucket, return 429 with a Retry-After header and apply stricter limits to costly endpoints. Share the counter across servers.", ["Counters per key", "Token bucket or window", "429 and Retry-After"], ["How would you avoid blocking a whole office behind one IP?"]),
    q("database", "easy", ["sql-nosql"], "When would you choose PostgreSQL over MongoDB for a project?", "Choose PostgreSQL when data is relational, consistency and transactions matter and you need joins and reports. Choose MongoDB when data is document-shaped, changes shape often and is mostly read or written as a whole.", ["Relational vs document", "Transactions and joins", "Choose by access pattern"], ["Can PostgreSQL store JSON?"]),
    q("database", "medium", ["caching"], "How would you use Redis in a web application, and what is cache invalidation?", "Redis is a fast in-memory store used for caching query results, sessions, rate limits and queues. Invalidation means removing or updating cached data when the source changes; expiries and explicit deletes on writes keep it from going stale.", ["Fast in-memory store", "Typical uses", "Invalidate on change or expiry"], ["What is a cache stampede?"]),
    q("security", "medium", ["auth"], "Compare session cookies and JWT for authentication and explain how you would protect against XSS and CSRF.", "Sessions keep state on the server and send an id in a cookie, while JWTs carry signed claims the client sends. Escape output and use a content security policy against XSS, and use SameSite cookies and CSRF tokens against CSRF; httpOnly cookies keep tokens from scripts.", ["Server state vs signed token", "XSS: escape and CSP", "CSRF: SameSite and tokens"], ["How would you log a user out of a JWT system?"]),
    q("ai", "easy", ["llm-api"], "How would you add an LLM-powered feature, such as summarising text, to an existing web app?", "Call the LLM provider from your server, never from the browser with a secret key, send a clear prompt with the text, handle timeouts and errors, limit input length and cost, and show the result as an assistant draft.", ["Call from the server", "Handle errors and cost", "Clear prompt and limits"], ["How would you test the prompt?"], roles=DEV),
    q("ai", "medium", ["rag"], "What is a chatbot built on retrieval over company documents and what are its main parts?", "It splits documents into chunks, turns them into embeddings stored in a vector database, retrieves the chunks nearest to a question and gives them to the LLM to answer, ideally with citations. Quality depends on chunking, retrieval and the prompt.", ["Chunks and embeddings", "Retrieve then generate", "Citations and evaluation"], ["How would you handle documents that change daily?"], roles=DEV),
    q("ai", "hard", ["cost-latency"], "Your LLM feature is slow and expensive in production. What can you do?", "Reduce prompt size, cache repeated answers, use a smaller model where it is good enough, stream responses so users see progress, batch or queue non-urgent work and set limits per user. Measure cost and quality together.", ["Shorter prompts and caching", "Smaller models and streaming", "Limits and measurement"], ["How would you check that a cheaper model is good enough?"], roles=DEV),
    q("devops", "medium", ["docker"], "How do you deploy a Node or Python app with Docker and keep configuration and secrets safe?", "Build an image with only what the app needs, run it with environment variables or a secrets manager for configuration, never bake secrets into the image or commit them, and use a health check and a restart policy.", ["Small image", "Secrets outside the image", "Health checks"], ["How do you handle database migrations at deploy time?"]),
    q("git", "easy", ["workflow"], "Describe a Git workflow your team could use for features, reviews and releases.", "Create a short-lived branch per feature, open a pull request for review and automated checks, merge to main when approved and tag releases. Small pull requests and clear commit messages make review easier.", ["Branch per feature", "Pull request review and checks", "Small changes"], ["How do you handle a hotfix?"]),
    q("testing", "medium", ["api-testing"], "How would you test a REST API endpoint that creates a user?", "Test the success case, validation errors, duplicate emails, authorisation and the stored result, with a clean test database for each run. Check status codes and response shape.", ["Success and failure paths", "Authorisation and duplicates", "Clean test data"], ["How do you test an endpoint that sends an email?"]),
    q("dev-scenario", "medium", ["performance"], "Scenario: your Node API response time grows from 100 ms to 3 seconds after a new release. How do you find the cause?", "Compare metrics before and after the release, look at slow query logs and traces, check for a new N+1 query, missing index or blocking code, reproduce with a profile and fix, then add a performance check.", ["Compare before and after", "Traces and slow queries", "Fix and add a check"], ["How could you detect this before release?"], kind="scenario"),
    q("dev-scenario", "hard", ["design"], "Scenario: design the backend for a ride tracking app that shows a driver's live location to a customer.", "Drivers send location updates to the server, which publishes them to subscribed customers through WebSockets using pub/sub, stores recent points in a fast store and writes history asynchronously. Limit update frequency and protect access so only the booked customer sees the driver.", ["Updates via WebSocket and pub/sub", "Fast store for latest position", "Privacy and update limits"], ["How would you cope with weak mobile connections?"], kind="scenario"),
    q("javascript", "medium", ["javascript"], "What are debounce and throttle and when would you use each in a search box and a scroll handler?", "Debounce waits until the user stops triggering the event for a set time before running, which suits a search box so you do not call the API on every key press. Throttle runs at most once per interval, which suits scroll or resize handlers.", ["Debounce waits for a pause", "Throttle limits the rate", "Search box vs scroll"], ["How would you implement debounce with a timer?"]),
    q("project", "easy", ["projects"], "Describe a project you built with React, Node or Python. Which part was hardest and how did you deploy it?", "A strong answer states what the app does, your role, the hardest problem and its fix, and how it was deployed and tested.", ["Clear purpose and role", "Hardest problem and fix", "Deployment and testing"], ["What would you improve first?"], kind="scenario", roles=DEV),
]


def build():
    return write("devsinc", DEV, ITEMS)


if __name__ == "__main__":
    build()
